export default async function ResetPassword({searchParams}:{searchParams:Promise<{error?:string}>}){const q=await searchParams;return <main><div className="container"><div className="formCard" style={{maxWidth:520}}><span className="eyebrow">Vendor portal</span><h1>Choose a new password.</h1>{q.error&&<div className="notice error">{q.error}</div>}<form action="/api/auth/update-password" method="post"><div className="field"><label>New password</label><input name="password" type="password" minLength={8} required/></div><button className="btn primary" style={{width:"100%",marginTop:18}}>Update Password</button></form></div></div></main>}
